'use client';

import * as React from 'react';
import {createComponent} from '@lit/react';
import '@material/web/labs/gb/components/divider/md-gb-divider.js';
import {DividerElement} from '@material/web/labs/gb/components/divider/divider-element.js';

/**
 * A Material Design component. Wraps <md-gb-divider>.
 * Docs: https://material-web.dev/3.0/components/divider/
 */
export const MdDivider = createComponent({
  react: React,
  tagName: 'md-gb-divider',
  elementClass: DividerElement,
});

export type MdDividerProps = React.ComponentProps<typeof MdDivider>;
